											<v-card-title>جهت ثبت درخواست وام ابتدا باید ثبت نام خود را تکمیل نمایید</v-card-title>
										</v-img>
										<v-alert type="error" outlined>
											اطلاعات پارامترهای مشتری معتبر نمی باشد
										</v-alert>
									</div>
